    end
%[text] After training, store the training and validation histories and save the model parameters corresponding to the best validation performance. 
% Build tables to store the training and validation info
    TrainingHistory = table(trainIter,trainEpoch,trainLR,trainLoss,...
        VariableNames={'Iteration','Epoch','LearnRate','Loss'});
    ValidationHistory = table(valIter,valLoss,...
        VariableNames={'Iteration','Loss'});
    info = struct();
    info.TrainingHistory = TrainingHistory;
    info.ValidationHistory = ValidationHistory;
    cfg.TrainingInfo = info;
    % Save best parameters by validation loss
    p = pBest;
    % Save the network and informational struct cfg
    mName = cfg.ModelName;
    baseName = strjoin([mName, ts], "_");
    outpath = fullfile(outdir,baseName + ".mat");
    save(outpath,"p","cfg");
else
    % Skip training when loading pretrained model
end %[output:group:8481ed1c]
%%
%[text] ## Test the Network
%[text] Evaluate the trained model on randomly selected samples from the validation set and compare predictions against the original FEA solutions. 
if doTrain
    % Skip loading when the model was just trained
else
    % Load in pretrained network and configuration
    fName = fullfile(outdir, loadFile + ".mat");
    warning('off'); 
    S = load(fName,"p","cfg");
    warning('on');
    % Use gather on gpuArrays if running on CPU
    if useGpu == false
        S.p = dlupdate(@gather, S.p);
    end
    p = S.p; cfg = S.cfg;
end
%[text] Choose a small number of random samples from the validation set to view the results and compare against FEA. 
numTests = 3;
idxTest = randi([1,numel(cfg.IdxVal)],numTests,1);
for i=1:numTests %[output:group:0bb8ebe1]
    % Load the corresponding FEA results for the selected sample
    fileIdx = cfg.IdxVal(idxTest(i));
    testFileName = sprintf("EM_results_%03d.mat",fileIdx);
    load(testFileName);
    
    % Prepare network inputs
    bushing = findNodes(D.Mesh,"region",Cell=2);
    [Xs,Xes,Ys,As,Bs] = meshgraphnet.preprocessData(D,bushing);
    
    % Normalize inputs using training-set statistics
    normXs = utils.applyScale(Xs,cfg.InputOffset,cfg.InputScale);
    normXes = utils.applyScale(Xes,cfg.EdgeOffset,cfg.EdgeScale);
    Bs = blkdiag(Bs);
    Bs = Bs ./ sum(Bs,2);
    
    % Predict electric potential
    Ypred = meshgraphnet.meshgraphnet(p,normXs,normXes,Bs,cfg);
    Ypred = extractdata(Ypred);
    if useGpu
        Ypred = gather(Ypred);
    end
    
    % Rescale predictions back to physical units
    Ypred = utils.applyInverseScale(Ypred,cfg.OutputOffset,cfg.OutputScale);

    % Visualization and error analysis
    % Plot results on the transformer bushing only (exclude surrounding air)
    elemsBushing = findElements(D.Mesh,"region",Cell=2); 
    nodesBushing = findNodes(D.Mesh,"region",Cell=2);
    clims = [min(D.Potential), max(D.Potential)];
    figure(); %[output:66a349c3] %[output:005a8275] %[output:6e6a25b7]
    tiledlayout(1,3); %[output:66a349c3] %[output:005a8275] %[output:6e6a25b7]
    % FEA solution
    nexttile;
    pdeplot3D(D.Mesh.Nodes, ...
        D.Mesh.Elements(:,elemsBushing), ...
        ColorMapData=D.Potential);
    title('FEA Solution'); clim(clims);
    % AI prediction
    nexttile;
    % Our MGN makes predictions on the bushing nodes only, pad the rest with zeros
    numNodes = size(D.Mesh.Nodes,2);
    paddedYpred = zeros(numNodes,1);
    paddedYpred(nodesBushing) = Ypred;
    pdeplot3D(D.Mesh.Nodes, ...
        D.Mesh.Elements(:,elemsBushing), ...
        ColorMapData=paddedYpred); 
    title('AI Prediction'); clim(clims);
    % Compute the relative L2 error on the bushing nodes
    relErrorL2 = norm(Ypred'-D.Potential(nodesBushing))/norm(D.Potential(nodesBushing));
    title(sprintf('AI Prediction: Relative L2 error = %0.1e', relErrorL2));
    % Plot the relative error
    nexttile;
    absError = abs(paddedYpred-D.Potential);
    relError = absError./max(D.Potential(nodesBushing));
    pdeplot3D(D.Mesh.Nodes, ...
        D.Mesh.Elements(:,elemsBushing), ...
        ColorMapData=relError);
    title('Relative Error')
    clim([min(relError(nodesBushing)) max(relError(nodesBushing))])
end %[output:group:0bb8ebe1]
%%
%[text] ## Make Inference on New Design
%[text] This section demonstrates how to use the trained MeshGraphNet model to make predictions on a new design for which no high-fidelity simulation data is available. Given a new geometry defined by an STL file, the model predicts the electric potential field directly from geometry information. This enables rapid evaluation of new designs without running a full electrostatic simulation.
%[text] Load the STL file representing the transformer bushing insulator geometry. The STL file is assumed to be located in the `STL/` subdirectory. 
gmBushing = fegeometry("STL/TEST_bushing.stl");
%[text] Visualize the bushing insulator geometry. 
figure();  %[output:6f426dbf]
pdegplot(gmBushing); %[output:6f426dbf]
title("New Bushing Insulator Geometry"); %[output:6f426dbf]
%%
%[text] Create an electrostatic FEA model.
model = femodel(AnalysisType="electrostatic",Geometry=gmBushing); 
%[text] Define points in the domain at which predictions are made. Do this by generating a mesh.  
model = generateMesh(model,Hmax=0.025);
%%
%[text] Prepare the inputs. 
%[text] Extract the mesh and preprocess to build graph. 
data.Mesh = model.Mesh;
keep = []; % Keep all nodes since only passing the mesh on the bushing
[Xs,Xes,~,~,Bs] = meshgraphnet.preprocessData(data,keep);
%[text] Normalize inputs using training-set statistics. 
normalXs = utils.applyScale(Xs,cfg.InputOffset,cfg.InputScale);
normalXes = utils.applyScale(Xes,cfg.EdgeOffset,cfg.EdgeScale);
Bs = blkdiag(Bs);
Bs = Bs ./ sum(Bs,2);
%[text] Predict electric potential. 
PredPotential = meshgraphnet.meshgraphnet(p,normalXs,normalXes,Bs,cfg);
%[text] Rescale predictions back to physical units.
PredPotential = utils.applyInverseScale(PredPotential,cfg.OutputOffset,cfg.OutputScale);
PredPotential = extractdata(PredPotential)';
if useGpu
    PredPotential = gather(PredPotential);
end
%[text] Visualize predicted electric potential on the bushing insulator.
figure(); %[output:677e5848]
pdeplot3D(model.Mesh, ... %[output:677e5848]
    ColorMapData=PredPotential);  %[output:677e5848]
title('AI Predicted Electric Potential')  %[output:677e5848]
%%
%[text] ## Derive the Electric Field from the Predicted Potential
%[text] In the FEA workflow, the electric field is derived from the potential: $\\mathbf{E} = -\\nabla V$. We follow the same approach here, computing the gradient of the AI-predicted potential using FEA shape function derivatives on the tetrahedral mesh (see the helper function `electricFieldFromTetrahedra.m` in `src/+utils`). 
out = utils.electricFieldFromTetrahedra(model.Mesh.Nodes,model.Mesh.Elements,PredPotential);
Emag = out.Emag_node;
pdeplot3D(model.Mesh, ... %[output:30da2e88]
            ColorMapData=Emag); %[output:30da2e88]
title('Electric field magnitude derived from AI predictions') %[output:30da2e88]
%%
%[text] %[text:anchor:TMP_36ef] **References**
%[text] %[text:anchor:M_5694] 1. Pfaff, Tobias, Meire Fortunato, Alvaro Sanchez-Gonzalez, and Peter W. Battaglia. "Learning Mesh-Based Simulation with Graph Networks."  arXiv, June 18, 2021. [https://arxiv.org/abs/2010.03409](https://arxiv.org/abs/2010.03409).  \

